  let asnDragState = null;

  function initASNDrag() {
    document.querySelectorAll('.asn-chip').forEach(chip => {
      chip.addEventListener('pointerdown', asnStartDrag);
    });
  }

  function asnStartDrag(e) {
    e.preventDefault();
    const chip = e.currentTarget;
    const rect = chip.getBoundingClientRect();
    const ghost = document.createElement('span');
    ghost.className = 'asn-chip-ghost';
    ghost.textContent = chip.textContent;
    ghost.style.left = rect.left + 'px';
    ghost.style.top = rect.top + 'px';
    document.body.appendChild(ghost);
    chip.classList.add('dragging');
    asnDragState = {
      chip, ghost,
      offsetX: e.clientX - rect.left,
      offsetY: e.clientY - rect.top,
    };
    chip.setPointerCapture(e.pointerId);
    chip.addEventListener('pointermove', asnMoveDrag);
    chip.addEventListener('pointerup', asnEndDrag);
    chip.addEventListener('pointercancel', asnEndDrag);
  }

  function asnMoveDrag(e) {
    if (!asnDragState) return;
    asnDragState.ghost.style.left = (e.clientX - asnDragState.offsetX) + 'px';
    asnDragState.ghost.style.top  = (e.clientY - asnDragState.offsetY) + 'px';
    asnDragState.ghost.style.display = 'none';
    const under = document.elementFromPoint(e.clientX, e.clientY);
    asnDragState.ghost.style.display = '';
    const bucket = under?.closest('.asn-bucket');
    document.querySelectorAll('.asn-bucket').forEach(b => b.classList.toggle('drop-target', b === bucket));
  }

  function asnEndDrag(e) {
    if (!asnDragState) return;
    const { chip, ghost } = asnDragState;
    ghost.style.display = 'none';
    const under = document.elementFromPoint(e.clientX, e.clientY);
    ghost.remove();
    chip.classList.remove('dragging');
    document.querySelectorAll('.asn-bucket').forEach(b => b.classList.remove('drop-target'));
    const bucket = under?.closest('.asn-bucket');
    if (bucket) {
      const dest = bucket.dataset.truth;
      const correct = chip.dataset.truth;
      bucket.querySelector('.asn-bucket-contents').appendChild(chip);
      if (dest !== correct) {
        chip.classList.add('wrong-drop');
        setTimeout(() => {
          chip.classList.remove('wrong-drop');
          document.getElementById('asnSource').appendChild(chip);
        }, 600);
      }
    }
    chip.removeEventListener('pointermove', asnMoveDrag);
    chip.removeEventListener('pointerup', asnEndDrag);
    chip.removeEventListener('pointercancel', asnEndDrag);
    asnDragState = null;
  }

  function resetASN() {
    const source = document.getElementById('asnSource');
    document.querySelectorAll('.asn-bucket-contents .asn-chip').forEach(chip => {
      chip.classList.remove('wrong-drop');
      source.appendChild(chip);
    });
  }

  function solveASN() {
    document.querySelectorAll('.asn-chip').forEach(chip => {
      chip.classList.remove('wrong-drop');
      const truth = chip.dataset.truth;
      const bucket = document.querySelector('.asn-bucket[data-truth="' + truth + '"] .asn-bucket-contents');
      bucket.appendChild(chip);
    });
  }

  initASNDrag();


  function pickHingeOption(btn) {
    if (btn.classList.contains('dimmed')) return;
    const isCorrect = btn.dataset.correct === 'true';
    btn.classList.add('selected', isCorrect ? 'correct' : 'incorrect');
    // dim other options
    document.querySelectorAll('.hinge-opt').forEach(o => {
      if (o !== btn) o.classList.add('dimmed');
    });
    // show feedback for this option
    document.querySelectorAll('.hinge-feedback').forEach(f => f.classList.remove('visible'));
    const fbId = btn.dataset.feedbackId;
    if (fbId) document.getElementById(fbId).classList.add('visible');
  }

  function resetHinge() {
    document.querySelectorAll('.hinge-opt').forEach(o => {
      o.classList.remove('selected', 'correct', 'incorrect', 'dimmed');
    });
    document.querySelectorAll('.hinge-feedback').forEach(f => f.classList.remove('visible'));
  }

// Place each strategy section in its phase: ASN in AS A CLASS (after Section 4), hinge after the Quick check (7)
(function () {
  const asn = document.getElementById('asnSection');
  const match = document.getElementById('matchArea');
  if (asn && match) match.closest('section').after(asn);
  const hinge = document.getElementById('hingeSection');
  const cp = document.getElementById('checkpointGrid');
  if (hinge && cp) cp.closest('section').after(hinge);
})();

// Topic-specific instructions for the frame's fixed section text
(function () {
  const set = (sel, html) => { const el = document.querySelector(sel); if (el) el.innerHTML = html; };
  const v = document.querySelector('.vocab-grid');
  const vd = v && v.parentElement.querySelector('.sec-desc');
  if (vd) vd.innerHTML = 'Tap each card to flip and reveal the definition. You\'ll use these six terms all lesson.';
  const m = document.getElementById('matchArea');
  const md = m && m.parentElement.querySelector('.sec-desc');
  if (md) md.textContent = 'Click a dot plot, then click the description of its shape. There are five matching pairs.';
  const wd = document.getElementById('weDoGrid');
  const tip = wd && wd.parentElement.querySelector('.parts-instructions');
  if (tip) tip.innerHTML = '💡 <strong>Why we do it this way:</strong> one number never tells the whole story. Mia\'s supermarket job pays more in a typical week (higher median) and is far more predictable (smaller range), but the café\'s long right tail means some weeks pay much more. Use the same routine in the You do practice: <strong>centre → spread → shape → write the comparison with values</strong>.';
  set('#tier1-body .sec-desc', 'Read values straight off each plot. Type just the number (no units or $), a single letter, or a single shape word.');
  set('#tier2-body .sec-desc', 'Even-sized data sets, back-to-back plots and an outlier. When there is an even number of values, the median is halfway between the two middle values.');
  set('#tier3-body .sec-desc', 'Outliers, missing values and a money decision. Show your working on paper, then type just the number.');
})();
